package com.example.kazanamaziasistani;
import android.app.Notification; import android.app.NotificationChannel; import android.app.NotificationManager; import android.app.Service; import android.content.Intent; import android.content.pm.ServiceInfo; import android.os.Build; import android.os.IBinder; import android.os.PowerManager;
public class KeepAliveService extends Service { private PowerManager.WakeLock wakeLock; @Override public void onCreate() { super.onCreate(); String channelId = "app_background"; Notification notification; if (Build.VERSION.SDK_INT >= 26) { NotificationChannel channel = new NotificationChannel(channelId, "Arka plan çalışması", NotificationManager.IMPORTANCE_LOW); getSystemService(NotificationManager.class).createNotificationChannel(channel); notification = new Notification.Builder(this, channelId).setContentTitle(getString(R.string.app_name)).setContentText("Uygulama arka planda çalışıyor").setSmallIcon(android.R.drawable.ic_lock_idle_alarm).build(); } else { notification = new Notification.Builder(this).setContentTitle(getString(R.string.app_name)).setContentText("Uygulama arka planda çalışıyor").setSmallIcon(android.R.drawable.ic_lock_idle_alarm).build(); } if (Build.VERSION.SDK_INT >= 34) startForeground(1001, notification, ServiceInfo.FOREGROUND_SERVICE_TYPE_SPECIAL_USE); else startForeground(1001, notification); PowerManager pm = (PowerManager)getSystemService(POWER_SERVICE); wakeLock = pm.newWakeLock(PowerManager.PARTIAL_WAKE_LOCK, getPackageName()+":background"); wakeLock.acquire(); } @Override public int onStartCommand(Intent intent, int flags, int startId) { return START_STICKY; } @Override public void onDestroy() { if (wakeLock != null && wakeLock.isHeld()) wakeLock.release(); super.onDestroy(); } @Override public IBinder onBind(Intent intent) { return null; } }